class Editor:
    def __init__(self):
        self.doc = ''
        self.done = []
        self.undone = []

    def run(self, command):
        self.doc = command.do(self.doc)
        self.done.append(command)
        self.undone.clear()

    def undo(self):
        if self.done:
            command = self.done.pop()
            self.doc = command.undo(self.doc)
            self.undone.append(command)

    def redo(self):
        if self.undone:
            command = self.undone.pop()
            self.doc = command.do(self.doc)
            self.done.append(command)

