enum Event {
    Insert(String),
    Remove(usize),
    Clear,
}

fn apply(event: Event, items: &mut Vec<String>) {
    match event {
        Event::Insert(value) => items.push(value),
        Event::Remove(index) if index < items.len() => { items.remove(index); }
        Event::Remove(_) => {}
        Event::Clear => items.clear(),
    }
}

fn main() {
    let mut items = Vec::new();
    apply(Event::Insert(String::from("pattern")), &mut items);
    apply(Event::Remove(0), &mut items);
    apply(Event::Clear, &mut items);
    println!("{}", items.len());
}

from threading import Lock, Thread

def shared_counter():
    lock = Lock()
    count = 0
    def increment():
        nonlocal count
        for _ in range(100):
            with lock:
                count += 1
    workers = [Thread(target=increment) for _ in range(4)]
    for worker in workers:
        worker.start()
    for worker in workers:
        worker.join()
    return count

